edits.newText:
Future<void> activateNowPlayingJump() async {
  if (!isMounted()) return;
  final player = context.read<PlaybackController>();
  final track = player.songInfo?.track;
  if (track == null) return;
  if (!(player.songInfo?.isPlaying ?? false)) return;

  final parent = p.dirname(track.path);
  if (parent.isEmpty) return;
  if (ctrl.currentPath != parent) {
    await ctrl.loadFolder(parent);
  }
  if (!isMounted()) return;
  await scrollToTrack(track.path);
}

final Widget a11yNowPlayingJump = shouldExposeNowPlayingJump
    ? Semantics(
        label: 'jump to now-playing track',
        button: true,
        onTap: () => activateNowPlayingJump(),
        child: const Opacity(
          // Intentionally invisible: this is an accessibility-only action.
          opacity: 0.0,
          child: SizedBox(width: 1, height: 1),
        ),
      )
    : const SizedBox.shrink();

final Widget body = isDismissable
    ? Column(children: [
        _DragHandleAndCloseRegion(
          palette: theme.palette,
          onDragDownClose: onDragDownClose,
        ),
        Expanded(child: listBody),
      ])
    : listBody;

final Widget stackedBody = Stack(children: [body, Positioned(top: 0, left: 0, child: a11yNowPlayingJump)]);

return ownsController
    ? ChangeNotifierProvider<LibraryController>.value(
        value: ctrl, child: stackedBody)
    : stackedBody;

